window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b19576f800609875"]={"versions": [{"id": "FIG-b19576f800609875", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentenschnittstellendiagramm (AUTOSAR Adaptive Platform Profil mit <code>«aap...»</code>-Stereotypen).</li>\n<li><strong>Architektur-Kontext:</strong> Interaktion zwischen den funktionellen Clustern <strong>Platform Health Management (PHM)</strong> und <strong>State Management (SM)</strong> auf der AUTOSAR Adaptive Platform (Release R21-11).</li>\n<li><strong>Funktionaler Zweck:</strong> Bereitstellung eines standardisierten Recovery-Mechanismus bei Überwachungsfehlern (Alive-, Deadline-, Logical- oder Health-Channel-Supervision). Scheitert eine Überwachung in PHM, delegiert PHM die Einleitung von Fehlerbehebungsmaßnahmen (z. B. Prozess-Neustart, Zustandsübergang in Safe State) über die Schnittstelle <code>RecoveryAction</code> an das State Management.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionale Cluster:</strong></li>\n<li><code>«aapFunctionalCluster» State Management (daemon-based)</code>: Zielinstanz für Wiederherstellungsaktionen; realisiert und exponiert den Server-Port (<code>«aapProvidedPort»</code>) für die Recovery-Logik.</li>\n<li><code>«aapFunctionalCluster» Platform Health Management (daemon-based)</code>: Überwachungsinstanz; fungiert als Klient (<code>«use»</code>-Abhängigkeit) und ruft Recovery-Aktionen bei erkannten Anomalien auf.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Interface & Methoden:</strong></li>\n<li><code>«aapPortInterface, aapAPI» Platform Health Management::RecoveryAction</code>: Namensraum-zugehöriges Interface zur Fehlereskalation.</li>\n<li><code>+ Offer()</code>: Aktiviert die Dienstbereitschaft der Recovery-Schnittstelle im State Management.</li>\n<li><code>+ StopOffer()</code>: Zieht die Bereitstellung des Recovery-Services zurück.</li>\n<li><code>+ GetGlobalSupervisionStatus()</code>: Ermöglicht das synchrone Abfragen des aggregierten Überwachungsstatus aller überwachten Entitäten durch das State Management.</li>\n<li><code>«aapCallbackMethod» + RecoveryHandler()</code>: Asynchroner Benachrichtigungskanal/Callback, über den PHM das Eintreffen eines Überwachungsfehlers (Supervision Failure) an State Management meldet.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik:</strong></li>\n<li>State Management implementiert den Port (<code>«aapProvidedPort»</code>), d. h. SM stellt die Handler-Logik bereit.</li>\n<li>PHM bindet die Schnittstelle via <code>«use»</code> an, konsumiert den Service und triggert den <code>RecoveryHandler()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Service Offering:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM startet im Systemstart und ruft <code>Offer()</code> auf, um die Bereitschaft zur Entgegennahme von Recovery-Triggern zu signalisieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überwachung & Fehlerdetektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM erfasst Checkpoints von Adaptive Applications (<code>SupervisedEntity.ReportCheckpoint()</code>).</li>\n<li>Bei Verletzung von Timing-, Sequenz- oder Lebendigkeitsbedingungen wechselt der interne Status auf <code>EXPIRED</code> / <code>STOPPED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering der Recovery Action (asynchroner Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM initiiert den Call an <code>RecoveryHandler()</code> am State Management (daemon-übergreifendes IPC).</li>\n<li>Übergabeparameter umfassen typischerweise die Identifikation der fehlgeschlagenen Entität bzw. die konfigurierte Recovery-Aktions-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandsabfrage & Fehlerauflösung (synchroner Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM fragt bei Bedarf über <code>GetGlobalSupervisionStatus()</code> den Gesamtzustand ab, um kontextabhängige Zustandswechsel (z. B. Function Group State Transition via Execution Management) einzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei kontrolliertem Shutdown des State Managements wird der Dienst über <code>StopOffer()</code> deregistriert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Trennung:</strong> PHM entscheidet <em>wann</em> ein Fehler vorliegt, führt aber <em>keine</em> direkten Prozessabbrüche oder State-Transitions durch. Die Exekutivrechte zur Fehlerreaktion liegen exklusiv beim State Management (in Kooperation mit Execution Management).</li>\n<li><strong>Daemon-IPC-Kopplung:</strong> Da beide Entitäten als Daemons realisiert sind, erfolgt der Aufruf von <code>RecoveryHandler()</code> über die plattformspezifische IPC-Bindung (z. B. ara::com Binding oder direkte Unix Domain Sockets / Shared Memory).</li>\n<li><strong>Konfigurationsaspekt (ARXML):</strong></li>\n<li><code>PhmRecoveryActionInterface</code> muss im Manifest als Service-Port definiert und zwischen der <code>AdaptiveApplicationSwComponent</code> des PHM und des SM instanziiert (<code>ServiceInstanceToPortPrototypeMapping</code>) werden.</li>\n<li>Entwickler müssen sicherstellen, dass Timeouts auf <code>RecoveryHandler()</code> die Echtzeitanforderungen des Sicherheitskonzepts (FTTI – Fault Tolerant Time Interval) nicht verletzen.</li>\n<li><strong>Fehlerbehandlung:</strong> Bietet SM keinen Service (<code>Offer()</code> ausstehend), muss PHM plattformspezifische Fallbacks vorsehen (z. B. direkter Hardware-Watchdog-Trigger bei Nicht-Erreichbarkeit des State Managements).</li>\n</ul>"}, {"id": "FIG-86c868319a553b26", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentenschnittstellendiagramm (AUTOSAR Adaptive Platform Profil mit <code>«aap...»</code>-Stereotypen).</li>\n<li><strong>Architektur-Kontext:</strong> Interaktion zwischen den funktionellen Clustern <strong>Platform Health Management (PHM)</strong> und <strong>State Management (SM)</strong> auf der AUTOSAR Adaptive Platform (Release R21-11).</li>\n<li><strong>Funktionaler Zweck:</strong> Bereitstellung eines standardisierten Recovery-Mechanismus bei Überwachungsfehlern (Alive-, Deadline-, Logical- oder Health-Channel-Supervision). Scheitert eine Überwachung in PHM, delegiert PHM die Einleitung von Fehlerbehebungsmaßnahmen (z. B. Prozess-Neustart, Zustandsübergang in Safe State) über die Schnittstelle <code>RecoveryAction</code> an das State Management.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionale Cluster:</strong></li>\n<li><code>«aapFunctionalCluster» State Management (daemon-based)</code>: Zielinstanz für Wiederherstellungsaktionen; realisiert und exponiert den Server-Port (<code>«aapProvidedPort»</code>) für die Recovery-Logik.</li>\n<li><code>«aapFunctionalCluster» Platform Health Management (daemon-based)</code>: Überwachungsinstanz; fungiert als Klient (<code>«use»</code>-Abhängigkeit) und ruft Recovery-Aktionen bei erkannten Anomalien auf.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Interface & Methoden:</strong></li>\n<li><code>«aapPortInterface, aapAPI» Platform Health Management::RecoveryAction</code>: Namensraum-zugehöriges Interface zur Fehlereskalation.</li>\n<li><code>+ Offer()</code>: Aktiviert die Dienstbereitschaft der Recovery-Schnittstelle im State Management.</li>\n<li><code>+ StopOffer()</code>: Zieht die Bereitstellung des Recovery-Services zurück.</li>\n<li><code>+ GetGlobalSupervisionStatus()</code>: Ermöglicht das synchrone Abfragen des aggregierten Überwachungsstatus aller überwachten Entitäten durch das State Management.</li>\n<li><code>«aapCallbackMethod» + RecoveryHandler()</code>: Asynchroner Benachrichtigungskanal/Callback, über den PHM das Eintreffen eines Überwachungsfehlers (Supervision Failure) an State Management meldet.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik:</strong></li>\n<li>State Management implementiert den Port (<code>«aapProvidedPort»</code>), d. h. SM stellt die Handler-Logik bereit.</li>\n<li>PHM bindet die Schnittstelle via <code>«use»</code> an, konsumiert den Service und triggert den <code>RecoveryHandler()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Service Offering:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM startet im Systemstart und ruft <code>Offer()</code> auf, um die Bereitschaft zur Entgegennahme von Recovery-Triggern zu signalisieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überwachung & Fehlerdetektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM erfasst Checkpoints von Adaptive Applications (<code>SupervisedEntity.ReportCheckpoint()</code>).</li>\n<li>Bei Verletzung von Timing-, Sequenz- oder Lebendigkeitsbedingungen wechselt der interne Status auf <code>EXPIRED</code> / <code>STOPPED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering der Recovery Action (asynchroner Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM initiiert den Call an <code>RecoveryHandler()</code> am State Management (daemon-übergreifendes IPC).</li>\n<li>Übergabeparameter umfassen typischerweise die Identifikation der fehlgeschlagenen Entität bzw. die konfigurierte Recovery-Aktions-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandsabfrage & Fehlerauflösung (synchroner Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM fragt bei Bedarf über <code>GetGlobalSupervisionStatus()</code> den Gesamtzustand ab, um kontextabhängige Zustandswechsel (z. B. Function Group State Transition via Execution Management) einzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei kontrolliertem Shutdown des State Managements wird der Dienst über <code>StopOffer()</code> deregistriert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Trennung:</strong> PHM entscheidet <em>wann</em> ein Fehler vorliegt, führt aber <em>keine</em> direkten Prozessabbrüche oder State-Transitions durch. Die Exekutivrechte zur Fehlerreaktion liegen exklusiv beim State Management (in Kooperation mit Execution Management).</li>\n<li><strong>Daemon-IPC-Kopplung:</strong> Da beide Entitäten als Daemons realisiert sind, erfolgt der Aufruf von <code>RecoveryHandler()</code> über die plattformspezifische IPC-Bindung (z. B. ara::com Binding oder direkte Unix Domain Sockets / Shared Memory).</li>\n<li><strong>Konfigurationsaspekt (ARXML):</strong></li>\n<li><code>PhmRecoveryActionInterface</code> muss im Manifest als Service-Port definiert und zwischen der <code>AdaptiveApplicationSwComponent</code> des PHM und des SM instanziiert (<code>ServiceInstanceToPortPrototypeMapping</code>) werden.</li>\n<li>Entwickler müssen sicherstellen, dass Timeouts auf <code>RecoveryHandler()</code> die Echtzeitanforderungen des Sicherheitskonzepts (FTTI – Fault Tolerant Time Interval) nicht verletzen.</li>\n<li><strong>Fehlerbehandlung:</strong> Bietet SM keinen Service (<code>Offer()</code> ausstehend), muss PHM plattformspezifische Fallbacks vorsehen (z. B. direkter Hardware-Watchdog-Trigger bei Nicht-Erreichbarkeit des State Managements).</li>\n</ul>"}, {"id": "FIG-a58784c6f478bc6d", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentenschnittstellendiagramm (AUTOSAR Adaptive Platform Profil mit <code>«aap...»</code>-Stereotypen).</li>\n<li><strong>Architektur-Kontext:</strong> Interaktion zwischen den funktionellen Clustern <strong>Platform Health Management (PHM)</strong> und <strong>State Management (SM)</strong> auf der AUTOSAR Adaptive Platform (Release R21-11).</li>\n<li><strong>Funktionaler Zweck:</strong> Bereitstellung eines standardisierten Recovery-Mechanismus bei Überwachungsfehlern (Alive-, Deadline-, Logical- oder Health-Channel-Supervision). Scheitert eine Überwachung in PHM, delegiert PHM die Einleitung von Fehlerbehebungsmaßnahmen (z. B. Prozess-Neustart, Zustandsübergang in Safe State) über die Schnittstelle <code>RecoveryAction</code> an das State Management.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionale Cluster:</strong></li>\n<li><code>«aapFunctionalCluster» State Management (daemon-based)</code>: Zielinstanz für Wiederherstellungsaktionen; realisiert und exponiert den Server-Port (<code>«aapProvidedPort»</code>) für die Recovery-Logik.</li>\n<li><code>«aapFunctionalCluster» Platform Health Management (daemon-based)</code>: Überwachungsinstanz; fungiert als Klient (<code>«use»</code>-Abhängigkeit) und ruft Recovery-Aktionen bei erkannten Anomalien auf.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Interface & Methoden:</strong></li>\n<li><code>«aapPortInterface, aapAPI» Platform Health Management::RecoveryAction</code>: Namensraum-zugehöriges Interface zur Fehlereskalation.</li>\n<li><code>+ Offer()</code>: Aktiviert die Dienstbereitschaft der Recovery-Schnittstelle im State Management.</li>\n<li><code>+ StopOffer()</code>: Zieht die Bereitstellung des Recovery-Services zurück.</li>\n<li><code>«aapCallbackMethod» + RecoveryHandler()</code>: Asynchroner Benachrichtigungskanal/Callback, über den PHM das Eintreffen eines Überwachungsfehlers (Supervision Failure) an State Management meldet.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik:</strong></li>\n<li>State Management implementiert den Port (<code>«aapProvidedPort»</code>), d. h. SM stellt die Handler-Logik bereit.</li>\n<li>PHM bindet die Schnittstelle via <code>«use»</code> an, konsumiert den Service und triggert den <code>RecoveryHandler()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Service Offering:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM startet im Systemstart und ruft <code>Offer()</code> auf, um die Bereitschaft zur Entgegennahme von Recovery-Triggern zu signalisieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überwachung & Fehlerdetektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM erfasst Checkpoints von Adaptive Applications (<code>SupervisedEntity.ReportCheckpoint()</code>).</li>\n<li>Bei Verletzung von Timing-, Sequenz- oder Lebendigkeitsbedingungen wechselt der interne Status auf <code>EXPIRED</code> / <code>STOPPED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering der Recovery Action (asynchroner Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM initiiert den Call an <code>RecoveryHandler()</code> am State Management (daemon-übergreifendes IPC).</li>\n<li>Übergabeparameter umfassen typischerweise die Identifikation der fehlgeschlagenen Entität bzw. die konfigurierte Recovery-Aktions-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>State Management verarbeitet den gemeldeten Überwachungsfehler und leitet entsprechende Wiederherstellungsmaßnahmen ein (z. B. Function Group State Transition via Execution Management oder Prozess-Neustart).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei kontrolliertem Shutdown des State Managements wird der Dienst über <code>StopOffer()</code> deregistriert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Trennung:</strong> PHM entscheidet <em>wann</em> ein Fehler vorliegt, führt aber <em>keine</em> direkten Prozessabbrüche oder State-Transitions durch. Die Exekutivrechte zur Fehlerreaktion liegen exklusiv beim State Management (in Kooperation mit Execution Management).</li>\n<li><strong>Daemon-IPC-Kopplung:</strong> Da beide Entitäten als Daemons realisiert sind, erfolgt der Aufruf von <code>RecoveryHandler()</code> über die plattformspezifische IPC-Bindung (z. B. ara::com Binding oder direkte Unix Domain Sockets / Shared Memory).</li>\n<li><strong>Konfigurationsaspekt (ARXML):</strong></li>\n<li><code>PhmRecoveryActionInterface</code> muss im Manifest als Service-Port definiert und zwischen der <code>AdaptiveApplicationSwComponent</code> des PHM und des SM instanziiert (<code>ServiceInstanceToPortPrototypeMapping</code>) werden.</li>\n<li>Entwickler müssen sicherstellen, dass Timeouts auf <code>RecoveryHandler()</code> die Echtzeitanforderungen des Sicherheitskonzepts (FTTI – Fault Tolerant Time Interval) nicht verletzen.</li>\n<li><strong>Fehlerbehandlung:</strong> Bietet SM keinen Service (<code>Offer()</code> ausstehend), muss PHM plattformspezifische Fallbacks vorsehen (z. B. direkter Hardware-Watchdog-Trigger bei Nicht-Erreichbarkeit des State Managements).</li>\n</ul>"}, {"id": "FIG-c1bde4e24dcfadf2", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponentenschnittstellendiagramm (AUTOSAR Adaptive Platform Profil mit <code>«aap...»</code>-Stereotypen).</li>\n<li><strong>Architektur-Kontext:</strong> Interaktion zwischen den funktionellen Clustern <strong>Platform Health Management (PHM)</strong> und <strong>State Management (SM)</strong> auf der AUTOSAR Adaptive Platform (Release R21-11).</li>\n<li><strong>Funktionaler Zweck:</strong> Bereitstellung eines standardisierten Recovery-Mechanismus bei Überwachungsfehlern (Alive-, Deadline-, Logical- oder Health-Channel-Supervision). Scheitert eine Überwachung in PHM, delegiert PHM die Einleitung von Fehlerbehebungsmaßnahmen (z. B. Prozess-Neustart, Zustandsübergang in Safe State) über die Schnittstelle <code>RecoveryAction</code> an das State Management.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionale Cluster:</strong></li>\n<li><code>«aapFunctionalCluster» Platform Health Management (daemon-based)</code>: Überwachungsinstanz und Dienstanbieter; implementiert und realisiert die Schnittstelle <code>RecoveryAction</code>.</li>\n<li><code>«aapFunctionalCluster» State Management (daemon-based)</code>: Zielinstanz für Wiederherstellungsaktionen; fungiert als Klient (<code>«use»</code>-Abhängigkeit) der Schnittstelle <code>RecoveryAction</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Interface & Methoden:</strong></li>\n<li><code>«aapPortInterface, aapAPI» Platform Health Management::RecoveryAction</code>: Namensraum-zugehöriges Interface zur Fehlereskalation.</li>\n<li><code>+ Offer()</code>: Aktiviert die Dienstbereitschaft der Recovery-Schnittstelle im Platform Health Management.</li>\n<li><code>+ StopOffer()</code>: Zieht die Bereitstellung des Recovery-Services im Platform Health Management zurück.</li>\n<li><code>«aapCallbackMethod» + RecoveryHandler()</code>: Callback-Methode zur Signalisierung von Überwachungsfehlern an das State Management.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik:</strong></li>\n<li>Platform Health Management implementiert die Schnittstelle über eine Schnittstellenrealisierung (gestrichelte Linie mit weißer Dreiecksspitze).</li>\n<li>State Management bindet die Schnittstelle via <code>«use»</code> an und konsumiert den Dienst.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Service Offering:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Platform Health Management startet im Systemstart und ruft <code>Offer()</code> auf, um den Dienst <code>RecoveryAction</code> bereitzustellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Überwachung & Fehlerdetektion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM erfasst Checkpoints von Adaptive Applications (<code>SupervisedEntity.ReportCheckpoint()</code>).</li>\n<li>Bei Verletzung von Timing-, Sequenz- oder Lebendigkeitsbedingungen wechselt der interne Status auf <code>EXPIRED</code> / <code>STOPPED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Triggering der Recovery Action (Callback-Pfad):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM initiiert den Aufruf der Callback-Methode <code>RecoveryHandler()</code> am State Management (daemon-übergreifendes IPC).</li>\n<li>Übergabeparameter umfassen typischerweise die Identifikation der fehlgeschlagenen Entität bzw. die konfigurierte Recovery-Aktions-ID.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>State Management verarbeitet den gemeldeten Überwachungsfehler und leitet entsprechende Wiederherstellungsmaßnahmen ein (z. B. Function Group State Transition via Execution Management oder Prozess-Neustart).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei kontrolliertem Shutdown des Platform Health Managements wird der Dienst über <code>StopOffer()</code> deregistriert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Trennung:</strong> PHM entscheidet <em>wann</em> ein Fehler vorliegt, führt aber <em>keine</em> direkten Prozessabbrüche oder State-Transitions durch. Die Exekutivrechte zur Fehlerreaktion liegen exklusiv beim State Management (in Kooperation mit Execution Management).</li>\n<li><strong>Daemon-IPC-Kopplung:</strong> Da beide Entitäten als Daemons realisiert sind, erfolgt der Aufruf von <code>RecoveryHandler()</code> über die plattformspezifische IPC-Bindung (z. B. ara::com Binding oder direkte Unix Domain Sockets / Shared Memory).</li>\n<li><strong>Konfigurationsaspekt (ARXML):</strong></li>\n<li><code>PhmRecoveryActionInterface</code> muss im Manifest als Service-Port definiert und zwischen der <code>AdaptiveApplicationSwComponent</code> des PHM und des SM instanziiert (<code>ServiceInstanceToPortPrototypeMapping</code>) werden.</li>\n<li>Entwickler müssen sicherstellen, dass Timeouts auf <code>RecoveryHandler()</code> die Echtzeitanforderungen des Sicherheitskonzepts (FTTI – Fault Tolerant Time Interval) nicht verletzen.</li>\n<li><strong>Fehlerbehandlung:</strong> Bietet SM keinen Service (<code>Offer()</code> ausstehend), muss PHM plattformspezifische Fallbacks vorsehen (z. B. direkter Hardware-Watchdog-Trigger bei Nicht-Erreichbarkeit des State Managements).</li>\n</ul>"}], "trans": [{"from": "FIG-b19576f800609875", "to": "FIG-86c868319a553b26", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-86c868319a553b26", "to": "FIG-a58784c6f478bc6d", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Platform Health Management::RecoveryAction</code>: Die Methode <code>+ GetGlobalSupervisionStatus()</code> wurde aus der Port-Schnittstelle entfernt.</li>\n</ul>"}, {"from": "FIG-a58784c6f478bc6d", "to": "FIG-c1bde4e24dcfadf2", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>State Management daemon-based</code>: Die Beziehungsrichtung zur Schnittstelle <code>RecoveryAction</code> wurde umgekehrt; State Management greift nun als Klient über eine Abhängigkeitsbeziehung (<code>«use»</code>) auf die Schnittstelle zu (zuvor Schnittstellenbereitstellung via <code>«aapProvidedPort»</code>).</li>\n<li><code>Platform Health Management daemon-based</code>: Realisiert nun die Schnittstelle <code>RecoveryAction</code> über eine Schnittstellenrealisierung (gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze; zuvor Klient via <code>«use»</code>).</li>\n<li><code>«aapProvidedPort»</code>: Das Stereotyp am Port von State Management wurde entfernt.</li>\n</ul>"}]};
